yo_case('fresh YOLO approval grants immediate mode and truthful connection projection',function()use($yolo){$i=FG_OAuth::authenticate($yolo['token']['access_token']);yo_auth($yolo['token']['access_token']);$r=yo_list($yolo['grant']['id']);yo_assert($i['writes']&&$i['yolo']&&FG_Auth::write_mode()==='yolo'&&$r['yolo']&&$r['effective_yolo'],'YOLO unavailable after explicit consent');});
