yo_case('settings storage failure cannot return YOLO mode',function()use($yolo,$wpdb){yo_auth($yolo['token']['access_token']);$fault=static fn($sql)=>str_starts_with($sql,'SELECT option_value FROM ')&&str_contains($sql,"'fg_settings'")?'SELECT * FROM yo_deliberately_missing_settings':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$fault);try{yo_assert(FG_Auth::write_mode()==='read_only','Storage failure allowed writes');}finally{remove_filter('query',$fault);$wpdb->suppress_errors($prior);}});
final class YO_DB_Proxy {private $db;public function __construct($db){$this->db=$db;}public function __get($k){return $this->db->$k;}public function __set($k,$v){$this->db->$k=$v;}public function __call($m,$a){$r=$this->db->$m(...$a);return $m==='get_results'&&str_starts_with($a[0]??'','SHOW COLUMNS FROM `'.yo_t('grants').'`')?array_values(array_filter($r,static fn($x)=>$x['Field']!=='allow_yolo')):$r;}}
yo_case('migration marker requires verified allow_yolo column and retry preserves credentials',function()use(&$wpdb,$epoch,$yolo){$real=$wpdb;update_option('fg_oauth_schema','2');$wpdb=new YO_DB_Proxy($real);try{FG_OAuth::install();yo_assert(get_option('fg_oauth_schema')==='2','Marker advanced without column');}finally{$wpdb=$real;}FG_OAuth::maybe_upgrade();yo_assert(get_option('fg_oauth_schema')==='3'&&get_option('fg_oauth_epoch')===$epoch&&!is_wp_error(FG_OAuth::authenticate($yolo['token']['access_token'])),'Retry failed or changed credentials');});
